// Buf is read access to a (possibly virtual) byte buffer.
type Buf interface {
	// Len is the buffer length.
	Len() uint64
	// Get reads n (0..=8) little-endian bytes at off.
	Get(off, n uint64) (uint64, error)
	// Avail is the byte count seen by length-dependent layouts
	// (__buffer_size, size-discriminated unions). A measuring buffer has none.
	Avail() (uint64, error)
	// Present is the number of bytes actually present (only a measuring
	// buffer differs from Len).
	Present() uint64
	// Measuring is true for a Measure buffer and windows into it.
	Measuring() bool
}

// BufMut is write access to a (possibly virtual) byte buffer.
type BufMut interface {
	Buf
	// Zero clears n bytes at off.
	Zero(off, n uint64) error
	// Put writes the low n (0..=8) bytes of v little-endian at off.
	Put(off, n, v uint64) error
}

func rangeEnd(length, off, n uint64) (uint64, error) {
	end, c := bits.Add64(off, n, 0)
	if c != 0 {
		return 0, ErrOutOfBounds
	}
	if end > length {
		return 0, Short(end, length)
	}
	return end, nil
}

// Bytes is a Buf over a byte slice.
type Bytes []byte

func (b Bytes) Len() uint64 { return uint64(len(b)) }

func (b Bytes) Get(off, n uint64) (uint64, error) {
	end, err := rangeEnd(uint64(len(b)), off, n)
	if err != nil {
		return 0, err
	}
	var v uint64
	for i, x := range b[off:end] {
		v |= uint64(x) << (8 * uint(i))
	}
	return v, nil
}

func (b Bytes) Avail() (uint64, error) { return uint64(len(b)), nil }
func (b Bytes) Present() uint64        { return uint64(len(b)) }
func (b Bytes) Measuring() bool        { return false }

func (b Bytes) Zero(off, n uint64) error {
	end, err := rangeEnd(uint64(len(b)), off, n)
	if err != nil {
		return err
	}
	clear(b[off:end])
	return nil
}

func (b Bytes) Put(off, n, v uint64) error {
	end, err := rangeEnd(uint64(len(b)), off, n)
	if err != nil {
		return err
	}
	for i := range b[off:end] {
		b[off+uint64(i)] = byte(v >> (8 * uint(i)))
	}
	return nil
}

type sub struct {
	inner Buf
	base  uint64
}

// Sub returns a read-only window starting base bytes into d.
func Sub(d Buf, base uint64) (Buf, error) {
	if base > d.Len() {
		return nil, Short(base, d.Len())
	}
	return sub{inner: d, base: base}, nil
}

func (s sub) Len() uint64 { return s.inner.Len() - s.base }

func (s sub) Get(off, n uint64) (uint64, error) {
	if _, err := rangeEnd(s.Len(), off, n); err != nil {
		return 0, err
	}
	return s.inner.Get(s.base+off, n)
}

func (s sub) Avail() (uint64, error) {
	a, err := s.inner.Avail()
	if err != nil {
		return 0, err
	}
	if a < s.base {
		return 0, nil
	}
	return a - s.base, nil
}

func (s sub) Present() uint64 {
	p := s.inner.Present()
	if p < s.base {
		return 0
	}
	return p - s.base
}

func (s sub) Measuring() bool { return s.inner.Measuring() }

type subMut struct {
	sub
	m BufMut
}

// SubMut returns a writable window starting base bytes into d.
func SubMut(d BufMut, base uint64) (BufMut, error) {
	if base > d.Len() {
		return nil, Short(base, d.Len())
	}
	return subMut{sub: sub{inner: d, base: base}, m: d}, nil
}

func (s subMut) Zero(off, n uint64) error {
	if _, err := rangeEnd(s.Len(), off, n); err != nil {
		return err
	}
	return s.m.Zero(s.base+off, n)
}

func (s subMut) Put(off, n, v uint64) error {
	if _, err := rangeEnd(s.Len(), off, n); err != nil {
		return err
	}
	return s.m.Put(s.base+off, n, v)
}

// Virtual is a buffer with no storage: reads return zero except for bytes
// written with Put (at most K writes). Running a type's initializer over it
// yields the footprint implied by a set of dynamic parameters.
type Virtual struct {
	length uint64
	k      int
	offs   []uint64
	lens   []uint64
	vals   []uint64
}

// NewVirtual returns a virtual buffer of the given length holding up to k writes.
func NewVirtual(length uint64, k int) *Virtual {
	return &Virtual{length: length, k: k}
}

func (v *Virtual) Len() uint64 { return v.length }

func (v *Virtual) Get(off, n uint64) (uint64, error) {
	if _, err := rangeEnd(v.length, off, n); err != nil {
		return 0, err
	}
	var r uint64
	for i := uint64(0); i < n; i++ {
		pos := off + i
		var b uint64
		for w := len(v.offs) - 1; w >= 0; w-- {
			start := v.offs[w]
			if pos >= start && pos < start+v.lens[w] {
				b = (v.vals[w] >> (8 * (pos - start))) & 0xff
				break
			}
		}
		r |= b << (8 * i)
	}
	return r, nil
}

func (v *Virtual) Avail() (uint64, error) { return v.length, nil }
func (v *Virtual) Present() uint64        { return v.length }
func (v *Virtual) Measuring() bool        { return false }

func (v *Virtual) Zero(off, n uint64) error {
	_, err := rangeEnd(v.length, off, n)
	return err
}

func (v *Virtual) Put(off, n, val uint64) error {
	if _, err := rangeEnd(v.length, off, n); err != nil {
		return err
	}
	if len(v.offs) == v.k {
		return ErrUnsupported
	}
	v.offs = append(v.offs, off)
	v.lens = append(v.lens, n)
	v.vals = append(v.vals, val)
	return nil
}

// Measure is the short-buffer measuring source: a layout walk over it
// computes the size the bytes present imply. It is unbounded (no end check
// fails), but every read must lie inside the bytes present, length-dependent
// layouts have no size (Avail fails) and jagged walkers stop at an element
// that starts past the bytes present.
