// NewMeasure returns a measuring source over data.
func NewMeasure(data []byte) Measure { return Measure{data: data} }

func (m Measure) Len() uint64                       { return MaxU64 }
func (m Measure) Get(off, n uint64) (uint64, error) { return Bytes(m.data).Get(off, n) }
func (m Measure) Avail() (uint64, error)            { return 0, ErrUnsupported }
func (m Measure) Present() uint64                   { return uint64(len(m.data)) }
func (m Measure) Measuring() bool                   { return true }

// Measured refines the size error err of a walk over data: when the bytes
// present determine the value's size (measure over a Measure succeeds) and it
// exceeds data, it reports that exact size; otherwise it keeps err.
func Measured(err error, data []byte, measure func(Buf) (uint64, error)) error {
	if KindOf(err) != KindBufferTooSmall {
		return err
	}
	end, merr := measure(NewMeasure(data))
	if merr == nil && end > uint64(len(data)) {
		return Short(end, uint64(len(data)))
	}
	return err
}

// Layout holds the offsets (Off), byte lengths (Len) and per-field auxiliary
// values (Aux: element count for arrays, tag for enums, variant index for
// size-discriminated unions) computed by a layout walk, plus the total size.
type Layout struct {
	Off []uint64
	Len []uint64
	Aux []uint64
	End uint64
}

// NewLayout returns a zeroed layout for n fields.
func NewLayout(n int) *Layout {
	all := make([]uint64, 3*n)
	return &Layout{Off: all[:n:n], Len: all[n : 2*n : 2*n], Aux: all[2*n:]}
}

// OrZero returns l, or a zeroed layout for n fields when err is set (view
// accessors on bytes that no longer form a valid layout read zeros).
func OrZero(l *Layout, err error, n int) *Layout {
	if err != nil || l == nil {
		return NewLayout(n)
	}
	return l
}

/* ============================================================================
 * Accessor helpers (never panic: out-of-range reads return zero / nil)
 * ============================================================================ */

// Tail returns data[off:] or a short-buffer error.
func Tail(data []byte, off uint64) ([]byte, error) {
	if off > uint64(len(data)) {
		return nil, Short(off, uint64(len(data)))
	}
	return data[off:], nil
}

// ValidateAt validates a nested value stored at data[off:]; size errors are
// reported relative to data.
func ValidateAt(data []byte, off uint64, f func([]byte) (uint64, error)) (uint64, error) {
	t, err := Tail(data, off)
	if err != nil {
		return 0, err
	}
	n, err := f(t)
	if err != nil {
		return 0, Shifted(err, off)
	}
	return n, nil
}

// Slice returns data[off:off+n] (capacity limited to n), or nil when the
// range is not inside data.
func Slice(data []byte, off, n uint64) []byte {
	end, c := bits.Add64(off, n, 0)
	if c != 0 || end > uint64(len(data)) {
		return nil
	}
	return data[off:end:end]
}

// Rd reads n little-endian bytes at off (0 when out of range).
func Rd(data []byte, off, n uint64) uint64 {
	v, _ := Bytes(data).Get(off, n)
	return v
}

// Wr writes the low n bytes of v little-endian at off.
func Wr(data []byte, off, n, v uint64) error {
	return Bytes(data).Put(off, n, v)
}

// Copy copies src over data[off:off+len(src)] when the range is inside data.
func Copy(data []byte, off uint64, src []byte) error {
	dst := Slice(data, off, uint64(len(src)))
	if dst == nil && len(src) != 0 {
		return Short(satAdd(off, uint64(len(src))), uint64(len(data)))
	}
	copy(dst, src)
	return nil
}

// Grow returns b extended by n zero bytes.
func Grow(b []byte, n int) []byte {
	return append(b, make([]byte, n)...)
}
